def photo_panel(d, detailed=False):
    """Accessible radio controls work under the review server's script-free CSP."""
    prefix=d['id']
    radios=[];figures=[];buttons=[];rules=[]
    for i,f in enumerate(d['frames']):
        ident=prefix+'-state-'+str(i)
        radios.append(f'<input class="state-radio" type="radio" name="{prefix}-states" id="{ident}" '+('checked ' if i==d['default'] else '')+f'aria-label="{escape(f["label"])}">')
        image=f'<img src="{f["file"]}" alt="{escape(d["title"]+" — "+f["label"])}" width="1200" height="900" loading="lazy">'
        link=f['file'] if detailed else d['id']+'.html'
        caption=f'<figcaption>{escape(f["input"])}</figcaption>' if detailed else ''
        figures.append(f'<figure data-frame="{i}"><a class="image-button" href="{link}">{image}</a>{caption}</figure>')
        buttons.append(f'<label for="{ident}">{escape(f["label"])}</label>')
        rules.append(f'#{ident}:checked ~ .pictures [data-frame="{i}"]{{display:block}} #{ident}:checked ~ .phases label[for="{ident}"]{{background:var(--ink);color:var(--paper);border-color:var(--ink)}} #{ident}:focus-visible ~ .phases label[for="{ident}"]{{outline:3px solid var(--pink)}}')
    return '<div class="photo-panel">'+''.join(radios)+'<div class="pictures">'+''.join(figures)+'</div><div class="phases">'+''.join(buttons)+'</div><style>'+''.join(rules)+'</style></div>'

def static_publish(data):
    css=CSS+'''
    .photo-panel{position:relative}.state-radio,.filter-radio{position:absolute;width:1px;height:1px;margin:0;padding:0;opacity:0;overflow:hidden;clip-path:inset(50%)}figure{margin:0}.pictures figure{display:none}.pictures img{width:100%;height:auto;aspect-ratio:4/3;display:block}.pictures figcaption{font-size:13px;color:var(--muted);padding:12px 0 3px}.phases label,.controls label{cursor:pointer;border:1px solid var(--line);padding:5px 8px;border-radius:3px;font-size:11px}.controls label{padding:8px 13px;font-size:14px}.phases label:hover,.controls label:hover{border-color:var(--ink)}.single{max-width:1320px}.single-grid{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(250px,1fr);gap:35px;margin-top:25px}.single-copy p{font-size:16px}.single-copy .label{color:var(--pink);margin-top:20px}.single-nav{display:flex;gap:20px;justify-content:space-between;padding:25px 0;border-bottom:1px solid var(--line);font-size:13px}.single h1{font-size:clamp(34px,4vw,55px)}.single .mapid{margin-top:30px}#filter-primitives:checked~.grid .card[data-seq="Transformation"],#filter-transformation:checked~.grid .card[data-seq="Primitives"],#filter-changes:checked~.grid .card[data-change="no"]{display:none}#filter-all:checked~.controls label[for="filter-all"],#filter-primitives:checked~.controls label[for="filter-primitives"],#filter-transformation:checked~.controls label[for="filter-transformation"],#filter-changes:checked~.controls label[for="filter-changes"]{background:var(--ink);color:var(--paper)}.filter-radio:focus-visible~.controls{outline:2px solid var(--pink)}@media(max-width:800px){.single-grid{grid-template-columns:1fr}.single-nav{flex-wrap:wrap}}@media print{.pictures figure{display:block}.phases{display:none}.pictures figure~figure{display:none}}
    '''
    # The review server intentionally disallows JavaScript; use static links and CSS radios.
    page=(HERE/'index.html').read_text(encoding='utf-8')
    page=page.replace('<style>'+CSS+'</style>','<style>'+css+'</style>')
    controls=''.join(f'<input class="filter-radio" type="radio" id="filter-{key}" name="sequence" '+('checked ' if key=='all' else '')+f'aria-label="{label}">' for key,label in [('all','All 21'),('primitives','Primitives 15'),('transformation','Transformation 6'),('changes','New constructions')])
    controls+='<nav class="controls" aria-label="Filter halls">'+''.join(f'<label for="filter-{key}">{label}</label>' for key,label in [('all','All 21'),('primitives','Primitives 15'),('transformation','Transformation 6'),('changes','New constructions')])+'<small>Click an image to inspect its lineage</small></nav>'
    cards=[]
    for d in data:
        kind='data' if d['kind']=='Carry data' else ('new' if d['kind'] in ['New construction','New assembly','Replacement'] else '')
        cards.append(f'<article class="card" data-seq="{d["sequence"]}" data-change="'+('yes' if kind=='new' else 'no')+f'" id="card-{d["id"]}"><div class="mapid">{d["number"]:02d} / {d["id"]}</div><h2>{d["title"]}</h2>'+photo_panel(d)+f'<span class="tag {kind}">{d["kind"]}</span><p class="summary">{d["new"]}</p><footer><a href="{d["id"]}.html">Inspect lineage ↗</a><a href="files.html#{d["id"]}">Full files</a></footer></article>')
    a=page.index('<nav class="controls"');b=page.index('<section class="notes"')
    page=page[:a]+controls+'<div class="grid">'+''.join(cards)+'</div>'+page[b:]
    for d in data: page=page.replace('#hall='+d['id']+'"',d['id']+'.html"')
    (HERE/'index.html').write_text(page,encoding='utf-8')
    for i,d in enumerate(data):
        previous=f'<a href="{data[i-1]["id"]}.html">← {data[i-1]["title"]}</a>' if i else '<span>Start of the route</span>'
        following=f'<a href="{data[i+1]["id"]}.html">{data[i+1]["title"]} →</a>' if i<len(data)-1 else '<span>End of this capture pass</span>'
        nav='<nav class="single-nav">'+previous+'<a href="index.html#card-'+d['id']+'">All images</a>'+following+'</nav>'
        body='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+d['title']+' · Tutorial output gallery</title><style>'+css+'</style><main class="single">'+nav+f'<div class="mapid">{d["number"]:02d} / 21 · {d["sequence"]} · {d["id"]}</div><h1>{d["title"]}</h1><div class="single-grid"><div>'+photo_panel(d,True)+'</div><div class="single-copy"><span class="tag">'+d['kind']+'</span>'
        for label,key in [('Bring','carry'),('Add','new'),('Carry onward','onward')]:body+=f'<div class="label">{label}</div><p>{d[key]}</p>'
        body+='<div class="notebox">'+d['note']+f'</div><a href="files.html#{d["id"]}">Full learner files</a> · <a href="/book-review/commons/maps/{d["id"]}/tutorial.md">Tutorial text</a></div></div>'+nav+'<p class="caption">Unchanged learner code · Godot 4.6 · supplied camera, light and ground · specified synthetic inputs. Click an image for its full-resolution file. <a href="verification.json">Capture receipt</a>.</p></main></html>'
        (HERE/(d['id']+'.html')).write_text(body,encoding='utf-8')
    src=(HERE/'files.html').read_text(encoding='utf-8')
    for d in data:src=src.replace('index.html#hall='+d['id'],d['id']+'.html')
    (HERE/'files.html').write_text(src,encoding='utf-8')
def main():
    verification=json.loads((HERE/'verification.json').read_text())
    data=[]
    for index,(hall,title,kind,carry,new,onward,note) in enumerate(ROWS):
        frames=[dict(f,label=LABELS[f['state']]) for f in verification['frames'] if f['hall']==hall]
        assert frames,hall
        files=[str(p.relative_to(HERE)).replace('\\','/') for p in sorted((HERE/'sources'/hall).glob('*')) if p.is_file()]
        data.append(dict(id=hall,title=title,kind=kind,carry=carry,new=new,onward=onward,note=note,
            number=index+1,sequence='Primitives' if index<15 else 'Transformation',frames=frames,files=files,default=DEFAULT.get(hall,0)))
    (HERE/'gallery.json').write_text(json.dumps(data,indent=2),encoding='utf-8')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tutorial output gallery · Endless Museum</title><style>'''+CSS+'''</style>
<header><div class="eyebrow">Endless Museum / the learner’s objects / 17 October 2026</div><h1>What survives<br>the next room?</h1><p class="intro">An image gallery of what the tutorial code actually produces. Follow the point, its record, the face and the body. Inspect where we carry material forward—and where we make something new.</p><div class="stat"><span><strong>21</strong> halls</span><span><strong>36</strong> native renders</span><span><strong>2</strong> opening sequences</span></div>
<div class="route"><a href="#hall=Point_One">Point</a><b>→</b><a href="#hall=Point_Coordinates">Hold</a><b>→</b><a href="#hall=Point_Lines">Line</a><b>→</b><a href="#hall=Point_Trace">Record</a><b>→</b><a href="#hall=Point_Line_Grid">Address</a><b>↗</b><a href="#hall=Point_Triangle_Context">Face</a><b>→</b><a href="#hall=Primitives_Polythedra">Body</a><b>→</b><a href="#hall=Primitives_Columns">Generate</a><b>→</b><a href="#hall=Trans_Translation">Move</a><b>→</b><a href="#hall=Trans_Rotation">Turn</a><b>→</b><a href="#hall=Trans_Scale">Scale</a><b>→</b><a href="#hall=Trans_Body">Respond</a></div>
<p class="caption">Current coverage: Point Zero through Trans_Body. These are student programs on a supplied capture stage. Museum installations and later lessons are outside this pass.</p></header>
<main><nav class="controls" aria-label="Filter halls"><button data-filter="All" aria-pressed="true">All 21</button><button data-filter="Primitives" aria-pressed="false">Primitives 15</button><button data-filter="Transformation" aria-pressed="false">Transformation 6</button><button data-filter="changes" aria-pressed="false">New constructions</button><small id="count">21 halls · click an image to follow the lineage</small></nav><div class="grid" id="gallery"></div>
<section class="notes" id="findings"><div class="eyebrow">What the pictures let us see</div><h2>The lineage holds in different ways.</h2><div class="notes-grid"><div><h3>A drawing really travels.</h3><p>Trace creates one saved record. Grid reads it without changing it. Triangle and Polyhedra read the same original positions. That continuity is checked in native Godot.</p><a href="#hall=Point_Trace">Follow the saved drawing →</a></div><div><h3>A method can continue.</h3><p>The tetrahedron, cube and octahedron use FaceBody with different position data. The columns and letter sweep make a further construction. Reusing a method is a different claim from carrying an object.</p><a href="#hall=Primitives_Ignorance">Inspect the generators →</a></div><div><h3>A handoff needs naming.</h3><p>Pre replaces CubeBody with BoxBody. Scale replaces the rotating slab with a doorway. Body then keeps that doorway and changes its input. These transitions should stay explicit in the writing.</p><a href="#hall=Trans_Scale">Compare Scale and Body →</a></div></div>
<details class="method"><summary>How these images were made—and what they verify</summary><p>The exact current learner scripts were copied into an isolated Godot 4.6 project. Canonical tutorial code blocks were checked against the files. The stage adds a camera, lights and a ground plane; it adds no learner objects and changes no learner materials. Scene framing varies between lessons; every state within one lesson keeps the same presentation camera.</p><p>Inputs are specified under each enlarged image. Pickup uses the actual XRTools library with a synthetic controller. Trace receives deterministic positions and a synthetic release signal. Body receives a real viewport camera at specified positions, then switches to a fixed camera for the photograph. This is native software evidence, not a headset session or a test of human learning.</p><p>All 36 captures passed 115 capture and continuity checks. The archive was unchanged after Grid, Triangle and Polyhedra. All 63 copied source/support files have hashes, and the 42 canonical tutorial/final files were preserved. Existing lessons’ reconstruction and behaviour tests are separate from this gallery.</p><p>The images also expose presentation work still possible: the live coordinate labels can overlap the moved point or trace; Introduction’s scaling box is centred across y=0. These conditions are shown rather than silently redesigned.</p><p><a href="verification.json">Capture receipt</a> · <a href="native.json">Native checks and inputs</a> · <a href="files.html">Full learner files</a> · <a href="capture.gd">Capture harness</a> · <a href="contact-sheet.jpg">All 36 frames</a></p></details></section></main>
<footer>Reading the images is part of the review. They verify a produced state, not the whole argument of a lesson.</footer>
</html>'''
    (HERE/'index.html').write_text(page,encoding='utf-8')
    sections=[]
    for d in data:
        details=[]
        for name in d['files']:
            p=HERE/name
            if p.suffix=='.ttf':
                details.append(f'<p>{p.name} · supplied font, included in the <a href="learner-sources.zip">source snapshot ZIP</a>.</p>')
                continue
            if p.suffix!='.gd':
                details.append(f'<p><a href="{name}">{p.name}</a> · supplied asset / license</p>')
                continue
            lines='\n'.join(f'<span class="lineno">{i}</span>{escape(line)}' for i,line in enumerate(p.read_text(encoding='utf-8').splitlines(),1))
            details.append(f'<details open><summary>{escape(p.name)} · <a href="{name}">raw file</a></summary><pre><code>{lines}</code></pre></details>')
        sections.append(f'<section id="{d["id"]}"><div class="eyebrow">{d["number"]:02d} / {d["id"]}</div><h2>{d["title"]}</h2><p><a href="index.html#hall={d["id"]}">Rendered output</a> · <a href="/book-review/commons/maps/{d["id"]}/tutorial.md">Canonical tutorial</a></p>'+''.join(details)+'</section>')
    sourcepage='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gallery source files · Endless Museum</title><style>'+CSS+'</style><main class="code"><a href="index.html">← Output gallery</a><h1>The code behind the images.</h1><p>Unchanged learner files pinned on 17 October 2026. Shared camera, room and XRTools are supplied infrastructure; these files do not replace Day Zero.</p><nav>'+''.join(f'<a href="#{d["id"]}">{d["number"]:02d} {d["title"]}</a>' for d in data)+'</nav>'+''.join(sections)+'</main></html>'
    (HERE/'files.html').write_text(sourcepage,encoding='utf-8')
    static_publish(data)
    # Contact sheet is a labelled layout of untouched renders, not a substitute render.
    frames=verification['frames']; sheet=Image.new('RGB',(1600,((len(frames)+3)//4)*333),'#f5f2eb');draw=ImageDraw.Draw(sheet)
    font=ImageFont.truetype('C:/Windows/Fonts/segoeui.ttf',13)
    for i,f in enumerate(frames):
        x,y=(i%4)*400,(i//4)*333
        sheet.paste(Image.open(HERE/f['file']).resize((400,300)),(x,y))
        draw.text((x+8,y+305),f['hall']+' / '+LABELS[f['state']],font=font,fill='#282823')
    sheet.save(HERE/'contact-sheet.jpg',quality=90)
    # A shorter preview shows the main material chain without pretending to include every hall.
    ids=['Point_One','Point_Lines','Point_Trace','Point_Line_Grid','Point_Triangle_Context','Primitives_Polythedra','Point_Animatedcube','Primitives_Columns','Primitives_Melencolia','Trans_Rotation','Trans_Scale','Trans_Body']
    preview=Image.new('RGB',(1600,999),'#f5f2eb');draw=ImageDraw.Draw(preview)
    for i,id in enumerate(ids):
        d=next(d for d in data if d['id']==id);f=d['frames'][d['default']];x,y=(i%4)*400,(i//4)*333
        preview.paste(Image.open(HERE/f['file']).resize((400,300)),(x,y));draw.text((x+8,y+305),f'{d["number"]:02d}  {d["title"]}',font=font,fill='#282823')
    preview.save(HERE/'selected-outputs.jpg',quality=92)
    (HERE/'README.md').write_text('''# Tutorial output gallery

Current scope: 15 Primitives halls and 6 Transformation halls, through Trans_Body.

`python capture.py` copies exact learner scripts, validates canonical code blocks, imports an isolated Godot project, renders 36 states and checks continuity. `python capture.py --reuse` refreshes the same isolated project. `python publish.py` rebuilds the image gallery and source reader. Requires the local Godot path in capture.py, Python and Pillow; the repository supplies XRTools.

No museum code, tutorial text or reflective text is edited. Camera, environment and ground belong to the capture harness. Inputs are specified per image; source files and original files are hashed in verification.json. The unique temporary project prevents overwriting the learner’s own saved trace.

Verified scope: source agreement, native scene startup, 36 image captures, actual XRTools synthetic pickup/release, trace filtering and saving, archive identity through three consumers, resolution ownership, bounded resolution search and camera-driven doorway size. This is not a replacement for each lesson’s full reconstruction tests or a headset/human learning test.

Lineage review: Triangle returns to the original Trace archive, not the snapped Grid copy. Cube and octahedron reuse FaceBody with fresh data. Profiles uses a supplied font/sweep helper. Trans_Pre replaces CubeBody with BoxBody. Scale reuses BoxBody and parent-child structure to create a new doorway and a new comparison sphere. Body keeps that construction and adds a proximity input.

Presentation findings: Labels can overlap the movable point and trace. Introduction’s centred scaling box extends below y=0; the stage floor is lowered for that comparison. These are documented, not silently fixed.
''',encoding='utf-8')
    with zipfile.ZipFile(HERE/'learner-sources.zip','w',zipfile.ZIP_DEFLATED) as archive:
        for p in (HERE/'sources').rglob('*'):
            if p.is_file():archive.write(p,p.relative_to(HERE).as_posix())
        for name in ['README.md','verification.json','generated/ada_student_trace.scn']:
            archive.write(HERE/name,name)
    print('Published',len(data),'halls,',len(frames),'states.')
